import os
from dotenv import load_dotenv

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
load_dotenv(os.path.join(BASE_DIR, '.env'))


class Config:
    SECRET_KEY = os.getenv('SECRET_KEY', 'dev-secret-key')
    SQLALCHEMY_TRACK_MODIFICATIONS = False
    SQLALCHEMY_DATABASE_URI = os.getenv(
        'DATABASE_URL',
        'sqlite:///' + os.path.join(BASE_DIR, 'data.db')
    )


class DevelopmentConfig(Config):
    DEBUG = True
    ENV = 'development'


class ProductionConfig(Config):
    DEBUG = False
    ENV = 'production'


class TestingConfig(Config):
    TESTING = True
    SQLALCHEMY_DATABASE_URI = 'sqlite:///:memory:'


config_by_name = {
    'development': DevelopmentConfig,
    'production': ProductionConfig,
    'testing': TestingConfig,
    'default': DevelopmentConfig
}


def get_config():
    env = os.getenv('FLASK_ENV', 'development')
    return config_by_name.get(env, DevelopmentConfig)

from flask import Blueprint, request, jsonify
from app import db
from app.models.note import Note
from datetime import datetime

notes_bp = Blueprint('notes', __name__)

@notes_bp.route('/notes', methods=['POST'])
def create_note():
    data = request.get_json()

    if 'title' not in data or 'content' not in data or 'category' not in data:
        return jsonify({'error': 'Title, content, and category are required'}), 400

    note = Note(
        title=data['title'],
        content=data['content'],
        category=data['category'],
        created_at=datetime.utcnow(),
        updated_at=datetime.utcnow()
    )

    db.session.add(note)
    db.session.commit()

    return jsonify(note.to_dict()), 201

@notes_bp.route('/notes', methods=['GET'])
def get_notes():
    notes = Note.query.all()
    return jsonify([note.to_dict() for note in notes])

@notes_bp.route('/notes/<int:id>', methods=['PUT'])
def update_note(id):
    note = Note.query.get_or_404(id)
    data = request.get_json()

    if 'title' not in data or 'content' not in data or 'category' not in data:
        return jsonify({'error': 'Title, content, and category are required'}), 400

    note.title = data['title']
    note.content = data['content']
    note.category = data['category']
    note.updated_at = datetime.utcnow()

    db.session.commit()
    return jsonify(note.to_dict())

@notes_bp.route('/notes/<int:id>', methods=['DELETE'])
def delete_note(id):
    note = Note.query.get_or_404(id)
    db.session.delete(note)
    db.session.commit()
    return jsonify({'message': 'Note deleted successfully'})

from flask import Blueprint, request, jsonify
from app.models import db, Note

xxx = Blueprint('xxx', __name__)

@xxx.route('/notes', methods=['POST'])
def create_note():
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({"error": "Invalid data"}), 400
    note = Note(title=data['title'], content=data['content'])
    db.session.add(note)
    db.session.commit()
    return jsonify(note.to_dict()), 201

@xxx.route('/notes/<int:note_id>', methods=['PUT'])
def edit_note(note_id):
    data = request.get_json()
    if not data or ('title' not in data and 'content' not in data):
        return jsonify({"error": "Invalid data"}), 400
    note = Note.query.get(note_id)
    if not note:
        return jsonify({"error": "Note not found"}), 404
    if 'title' in data:
        note.title = data['title']
    if 'content' in data:
        note.content = data['content']
    db.session.commit()
    return jsonify(note.to_dict()), 200

@xxx.route('/notes/<int:note_id>', methods=['DELETE'])
def delete_note(note_id):
    note = Note.query.get(note_id)
    if not note:
        return jsonify({"error": "Note not found"}), 404
    db.session.delete(note)
    db.session.commit()
    return jsonify({"message": "Note deleted"}), 200

@xxx.route('/notes', methods=['GET'])
def organize_notes():
    notes = Note.query.all()
    organized_notes = [note.to_dict() for note in notes]
    return jsonify(organized_notes), 200
